#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# Clock-out Form Reminder: the setup wizard (#37 to #41, spec #19). The only
# supported installer. Each step gives a plain Why, What to do and an
# Example. The flow follows the prototype on prototype/setup-wizard (3a5a222).
#
#   npm run setup                      full first-time setup
#   npm run setup -- --step NAME       rerun one step
#   npm run setup -- --help
#
# Everything it captures goes to the git-ignored .dev.vars, which the
# checking deploy reads (docs/RUNBOOK.md, "Where the Deployment's values
# live"). Hosted on our account, it's run on a call: we sign in to
# Cloudflare, the client does the Connecteam steps.
#
# Helpers below are inherited from EH_Webhook's wizard (~/IDP/EH_Webhook/
# scripts/setup-wizard.sh at 0c5ec92): why / todo / next_up / ok / fail, the
# quiet wrangler calls and the session log with keys redacted.

ENV_FILE="${WIZARD_ENV_FILE:-.dev.vars}"

# Every step in the order setup runs them, and the ones --step can rerun (#19).
STEPS=(key timezone form timings quiet-hours recipients reminder-task sender alerts webhook test)
# Built so far; the rest arrive with #38 to #41.
BUILT_STEPS=(key)

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  RED=$(tput setaf 1)
else
  RED=""
fi

# why "line" ... : the step's purpose in plain language.
why() {
  printf '\n  %sWhy this step%s\n' "$BOLD" "$RESET"
  local l; for l in "$@"; do printf '    %s\n' "$l"; done
}

# todo "action" ... : numbered list of what the person will do in this step.
todo() {
  printf '\n  %sWhat to do%s\n' "$BOLD" "$RESET"
  local i=1 l line first
  for l in "$@"; do
    first=1
    # Wrap at 76 columns, continuation lines under the text, not the number.
    while IFS= read -r line; do
      if [[ -n "$first" ]]; then printf '    %s%d.%s %s\n' "$BLUE" "$i" "$RESET" "$line"; first=""
      else printf '       %s\n' "$line"; fi
    done < <(printf '%s\n' "$l" | fold -s -w 69 | sed 's/ *$//')
    i=$((i + 1))
  done
}

# example "line" ... : a worked example in real values (#18).
example() {
  printf '\n  %sExample%s\n' "$BOLD" "$RESET"
  local l; for l in "$@"; do printf '    %s%s%s\n' "$DIM" "$l" "$RESET"; done
  printf '\n'
}

ok()   { printf '  %s✓ %s%s\n' "$GREEN" "$1" "$RESET"; }
fail() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; }

# next_up "text": how this step leads into the next one.
next_up() { printf '\n  %sNext: %s%s\n' "$DIM" "$1" "$RESET"; }

# visit URL: open it, unless WIZARD_NO_BROWSER is set (the wizard's tests).
visit() {
  if [[ -n "${WIZARD_NO_BROWSER:-}" ]]; then note "Open: $1"; else open_url "$1" || note "Open: $1"; fi
}

# save KEY VALUE "label": store a value in .dev.vars behind one plain line.
save() {
  write_env "$1" "$2" >/dev/null
  ok "Saved $3."
}

# Wrangler, quietly. WIZARD_DETAILS keeps every wrangler call's full output
# (git-ignored, cleaned and redacted like the session log); the screen shows
# one plain line per step instead.
WIZARD_DETAILS="${WIZARD_DETAILS:-$PWD/setup-wizard-$(date +%Y%m%d-%H%M%S)-wrangler.log}"

# wr: run this repo's wrangler, streaming output (for `wrangler login`).
wr() { npx wrangler "$@"; }

# wr_quiet ARGS...: run wrangler non-interactively, its output kept out of
# sight: appended to $WIZARD_DETAILS and left in $WR_OUT.
wr_quiet() {
  local rc=0
  WR_OUT=$(npx wrangler "$@" < /dev/null 2>&1) || rc=$?
  { printf '\n$ wrangler %s   (exit %s, %s)\n' "$*" "$rc" "$(date +%H:%M:%S)"; printf '%s\n' "$WR_OUT"; } >> "$WIZARD_DETAILS"
  chmod 600 "$WIZARD_DETAILS" 2>/dev/null || true
  return "$rc"
}

# json_get FIELD: read one field of the JSON on stdin.
json_get() { node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{try{const v=JSON.parse(s)[process.argv[1]];process.stdout.write(v==null?"":String(v))}catch{}})' "$1"; }

# ── session log (#19, user story 70) ──────────────────────────────────────
# The screen clears at every stage, so keep a copy of the whole run to look
# back at or send to the integrator. `script` records the terminal while
# keeping it a real terminal, and hidden input (API keys) isn't echoed, so it
# isn't recorded. Afterwards the log is turned into plain text and every key
# and secret in .dev.vars is replaced with [redacted], in case one was pasted
# before its prompt appeared.

# clean_log FILE: strip terminal codes, then redact the values of every
# *KEY* / *SECRET* entry in $ENV_FILE.
clean_log() {
  local f="$1"
  [[ -f "$f" ]] || return 0
  perl -i -pe 's/\e\[[0-9;?]*[A-Za-z]//g; s/\e\][^\a]*\a//g; s/\e[()][A-Z0-9]//g; s/\r//g; s/[\x04\x08]//g' "$f"
  if [[ -f "$ENV_FILE" ]]; then
    local key val
    for key in $(grep -oE '^[A-Z_]*(KEY|SECRET)[A-Z_]*=' "$ENV_FILE" | tr -d '='); do
      val=$(_existing "$key" || true)
      (( ${#val} >= 6 )) || continue
      SECRET_VALUE="$val" perl -i -pe 's/\Q$ENV{SECRET_VALUE}\E/[redacted]/g' "$f"
    done
  fi
  chmod 600 "$f"
}

# ── steps ─────────────────────────────────────────────────────────────────

s_cloudflare() {
  stage "Cloudflare account"
  why "The reminder runs as a small program (a \"Worker\") on Cloudflare, in your" \
      "own account, so you own it and everything it stores. It needs the Workers" \
      "Paid plan (about US\$5 a month): one escalation can message every admin at" \
      "once, which is more than the free plan allows."
  todo "Sign in on the page that opens, and make sure the account is on Workers Paid (Workers & Pages > Plans)." \
       "Sign this computer in to that account when the next browser tab opens." \
       "Check that the account shown here is the right one."
  example "Plans page: \"Workers Paid · \$5/month\" is the current plan." \
          "Shown here afterwards: \"Example Pty Ltd  3f2a91c0…\""
  visit "https://dash.cloudflare.com/?to=/:account/workers/plans"
  confirm "Is your Cloudflare account on the Workers Paid plan?" || {
    fail "Upgrade to Workers Paid on the page above, then run this again."
    exit 1
  }
  printf '\n'
  say "Signing this computer in to Cloudflare (a browser tab may open)..."
  # `whoami` can exit 0 while signed out, so read what it says.
  if ! wr_quiet whoami || grep -qi "not authenticated" <<<"$WR_OUT"; then wr login; fi
  if ! wr_quiet whoami || grep -qi "not authenticated" <<<"$WR_OUT"; then
    fail "Couldn't read the signed-in Cloudflare account."
    exit 1
  fi
  printf '%s\n' "$WR_OUT" | grep -E "│|account|Account" | sed 's/^/  /' | head -12
  printf '\n'
  confirm "Is that the account the reminder should run on?" || {
    fail "Run 'npx wrangler logout', then run this again and sign in to the right account."
    exit 1
  }
  next_up "the Connecteam key it uses."
}

s_key() {
  stage "Connecteam: API key"
  why "The reminder uses this key to see clock-outs and form submissions, and to" \
      "send its messages. It's stored only on your Cloudflare account. It also" \
      "tells us your daily API allowance: this needs Connecteam's Expert plan" \
      "(10,000 calls a day) or above, or it would run out of calls by lunchtime."
  todo "On the page that opens (Connecteam: Settings > API keys), create a new key." \
       "Paste it here. It won't show as you type."
  example "Name the key \"Clock-out Form Reminder\" so you can tell it apart later."
  visit "https://app.connecteam.com/#/settings/integrations/api"
  local verdict kind
  while :; do
    ask_secret CT_API_KEY "Paste the Connecteam API key:" || { fail "No key given."; exit 1; }
    say "Checking the key..."
    verdict=$(CT_API_KEY="$CT_API_KEY" npm run --silent check-api-key 2>/dev/null || true)
    kind=$(printf '%s' "$verdict" | json_get kind)
    case "$kind" in
      ok)
        save CT_API_KEY "$CT_API_KEY" "the API key"
        ok "Key works. Daily API allowance: $(printf '%s' "$verdict" | json_get dayLimit) calls a day."
        break ;;
      below_expert)
        fail "This account's daily API allowance is $(printf '%s' "$verdict" | json_get dayLimit) calls."
        say "The reminder needs Connecteam's Expert plan or above (10,000 calls a day)."
        say "On a smaller plan it would run out of calls by lunchtime, and every"
        say "other integration on the account would stop with it. Upgrade the plan"
        say "in Connecteam (Settings > Billing), then run this again."
        exit 1 ;;
      rejected)
        fail "Connecteam didn't accept that key."
        confirm "Paste it again? (make sure you copied the whole key)" || exit 1 ;;
      *)
        fail "Couldn't check the key: $(printf '%s' "$verdict" | json_get detail)"
        confirm "Try again?" || exit 1 ;;
    esac
  done
  next_up "your time zone."
}

# Each built step by --step name.
run_step() {
  case "$1" in
    key) s_key ;;
  esac
}

usage() {
  cat <<USAGE
Clock-out Form Reminder setup

  npm run setup                    full first-time setup
  npm run setup -- --step NAME     rerun one step
  npm run setup -- --help          this message

Steps: ${STEPS[*]}
USAGE
}

run_wizard() {

ONLY=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --step) ONLY="${2:-}"; [[ -n "$ONLY" ]] || { usage >&2; exit 2; }; shift ;;
    -h|--help) usage; exit 0 ;;
    *) printf 'unknown option: %s\n\n' "$1" >&2; usage >&2; exit 2 ;;
  esac
  shift
done
if [[ -n "$ONLY" ]]; then
  [[ " ${STEPS[*]} " == *" $ONLY "* ]] || { printf 'unknown step: %s\n\n' "$ONLY" >&2; usage >&2; exit 2; }
  [[ " ${BUILT_STEPS[*]} " == *" $ONLY "* ]] || {
    printf 'The "%s" step isn'"'"'t in this version of the wizard yet.\n' "$ONLY" >&2
    exit 2
  }
fi

# ── prerequisites (before anything is asked, so a missing tool fails fast) ─
for _c in node npm npx git curl; do
  command -v "$_c" >/dev/null 2>&1 || { printf 'missing required tool: %s\n' "$_c" >&2; exit 1; }
done
grep -q '"name": "clock-out-form-reminder"' package.json 2>/dev/null \
  || { printf 'run this from the TC_TO_FORM_RMDR repo root\n' >&2; exit 1; }
[[ -d node_modules ]] || { printf 'installing dependencies...\n'; npm install; }

# The session log: record the run, then clean and redact it (see clean_log).
if [[ -z "${WIZARD_LOG:-}" && -t 0 && -t 1 ]] && command -v script >/dev/null 2>&1 && command -v perl >/dev/null 2>&1; then
  export WIZARD_LOG="$PWD/setup-wizard-$(date +%Y%m%d-%H%M%S).log"
  export WIZARD_DETAILS="${WIZARD_LOG%.log}-wrangler.log"
  # Ctrl-C stops the recorded wizard; this outer shell carries on to clean up.
  # A no-op handler, not `trap ''`: an ignored signal is inherited.
  trap ':' INT
  if script --version >/dev/null 2>&1; then
    script -q -e -c "$(printf '%q ' bash "$0" "$@")" "$WIZARD_LOG" && rc=0 || rc=$?   # Linux / WSL
  else
    script -q "$WIZARD_LOG" bash "$0" "$@" && rc=0 || rc=$?                            # macOS
  fi
  trap - INT
  clean_log "$WIZARD_LOG"
  clean_log "$WIZARD_DETAILS"
  printf '\n  %sA copy of this run is in %s (keys hidden). Send it to your integrator if anything looked wrong.%s\n\n' \
    "$DIM" "${WIZARD_LOG#"$PWD"/}" "$RESET"
  exit "$rc"
fi

if [[ -n "$ONLY" ]]; then
  TOTAL_STAGES=1
  run_step "$ONLY"
  printf '\n'
  note "Saved to $ENV_FILE. Apply it with: npm run deploy"
  note "(From the \"Turn it on\" step, the wizard deploys for you: #40.)"
  finish
  return
fi

TOTAL_STAGES=2
banner "Clock-out Form Reminder: setup"
s_cloudflare
s_key
finish
note "This version of the wizard ends here: the remaining steps (time zone onward)"
note "arrive with #38 to #41. Until then, fill in the rest of $ENV_FILE by hand,"
note "following docs/RUNBOOK.md."
}

run_wizard "$@"; exit
